const payload = $input.first().json.body ?? $input.first().json;
const values = [];
if (Array.isArray(payload.entry)) {
  for (const entry of payload.entry) for (const change of entry.changes ?? []) values.push(change.value ?? {});
} else values.push(payload.value ?? payload);
const output = [];
for (const value of values) {
  for (const status of value.statuses ?? []) {
    output.push({ json: { event_type: 'message_status', message_id: status.id ?? '', recipient_phone: status.recipient_id ?? '', status: status.status ?? 'unknown', timestamp: status.timestamp ? new Date(Number(status.timestamp) * 1000).toISOString() : new Date().toISOString(), conversation_id: status.conversation?.id ?? '', pricing_category: status.pricing?.category ?? '', errors: status.errors ?? [] } });
  }
  for (const message of value.messages ?? []) {
    output.push({ json: { event_type: 'incoming_message', message_id: message.id ?? '', customer_phone: message.from ?? '', message_type: message.type ?? 'unknown', text: message.text?.body ?? '', timestamp: message.timestamp ? new Date(Number(message.timestamp) * 1000).toISOString() : new Date().toISOString() } });
  }
}
return output.length ? output : [{ json: { event_type: 'ignored', received_at: new Date().toISOString() } }];
